import { createContext, useContext, useState } from 'react'
import { BrowserRouter, Link, Route, Routes, useNavigate, useParams } from 'react-router-dom'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity, AlertTriangle, ArrowUpRight, Bell, Building2, ChevronDown, ClipboardCheck, Clock3, FileText, Gauge, LayoutDashboard, Menu, MoreHorizontal, Play, Search, Settings, ShieldCheck, Sparkles, Truck, Users, Wrench, X, Zap } from 'lucide-react'
import { useLiveSensors } from './hooks/useLiveSensors'
import SensorChart from './components/SensorChart'
import PredictiMaintOverview from './components/DashboardWithSensorWall'
import './App.css'

const navItems = [{ label: 'Dashboard', icon: LayoutDashboard, path: '/dashboard' }, { label: 'Assets', icon: Gauge, path: '/assets' }, { label: 'Maintenance', icon: Wrench, count: '8', path: '/maintenance' }, { label: 'Alerts', icon: Bell, count: '12', path: '/alerts' }, { label: 'Analytics', icon: Activity, path: '/analytics' }]
const maintenanceQueue = [{ asset: 'P-104', risk: '89%', priority: 'Critical', issue: 'Bearing degradation', downtime: '18h', cost: '₹48,000' }, { asset: 'P-087', risk: '63%', priority: 'High', issue: 'Motor overheating', downtime: '9h', cost: '₹26,000' }, { asset: 'P-112', risk: '31%', priority: 'Medium', issue: 'Vibration anomaly', downtime: '4h', cost: '₹11,000' }]
const assetCatalog = [{ id: 'P-104', name: 'Pump P-104', type: 'Pump', location: 'Utilities plant', status: 'Critical', risk: 89, health: 72, anomaly: 'Bearing degradation', updated: '2 min ago' }, { id: 'P-087', name: 'Pump P-087', type: 'Pump', location: 'West campus', status: 'Warning', risk: 63, health: 78, anomaly: 'Motor overheating', updated: '8 min ago' }, { id: 'P-112', name: 'Pump P-112', type: 'Pump', location: 'Water treatment', status: 'Warning', risk: 31, health: 83, anomaly: 'Vibration anomaly', updated: '14 min ago' }, { id: 'M-017', name: 'Motor M-017', type: 'Motor', location: 'Engineering block', status: 'Normal', risk: 18, health: 91, anomaly: 'No active anomaly', updated: '4 min ago' }, { id: 'M-023', name: 'Motor M-023', type: 'Motor', location: 'North plant', status: 'Normal', risk: 11, health: 95, anomaly: 'No active anomaly', updated: '6 min ago' }, { id: 'G-003', name: 'Generator G-003', type: 'Generator', location: 'East plant', status: 'Warning', risk: 42, health: 81, anomaly: 'Temperature drift', updated: '11 min ago' }, { id: 'HVAC-21', name: 'HVAC HVAC-21', type: 'HVAC', location: 'Science block', status: 'Critical', risk: 76, health: 64, anomaly: 'Bearing anomaly', updated: '3 min ago' }]
const initialJob = { id: 'M-2041', asset: 'Pump P-104', assetId: 'P-104', issue: 'Bearing degradation', action: 'Inspect drive-end bearing', priority: 'Critical', technician: 'Rahul', due: 'Today, 4:00 PM', duration: '2.5 hours', notes: '', status: 'Predicted issue', created: 'Today, 12:25 PM' }
const JobContext = createContext(null)
function useJobs() { return useContext(JobContext) }

function Button({ children, variant = 'primary', icon: Icon, onClick }) { return <button type="button" className={`btn btn-${variant}`} onClick={onClick}>{Icon && <Icon size={16} strokeWidth={2} />}{children}</button> }
function Badge({ children, tone = 'neutral' }) { return <span className={`badge badge-${tone}`}>{children}</span> }
function StatusBadge({ status }) { return <Badge tone={status.toLowerCase()}><span className="status-dot" />{status}</Badge> }
function MetricCard({ label, value, detail, icon: Icon, tone = 'blue' }) { return <article className="metric-card"><div className={`metric-icon metric-${tone}`}><Icon size={18} /></div><div><p className="eyebrow">{label}</p><strong>{value}</strong><p className="metric-detail">{detail}</p></div></article> }
function Modal({ onClose }) { return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" onMouseDown={(event) => event.stopPropagation()}><button className="icon-button modal-close" onClick={onClose} aria-label="Close dialog"><X size={18} /></button><div className="modal-mark"><Sparkles size={22} /></div><h2 id="modal-title">AI maintenance brief</h2><p>RakshaAI has reviewed the latest Pump P-104 signals. The failure probability is 89% within 6 hours, with bearing degradation as the likely cause.</p><div className="brief-row"><span>Recommended next action</span><strong>Inspect bearing assembly</strong></div><Button onClick={onClose}>Review alert</Button></section></div> }
function CreateJobModal({ onClose, onCreated }) { const [form, setForm] = useState({ asset: 'Pump P-104', issue: 'Bearing degradation', action: 'Inspect drive-end bearing', priority: 'Critical', technician: 'Rahul', due: 'Today, 4:00 PM', duration: '2.5 hours', notes: '' }); const update = (field, value) => setForm((current) => ({ ...current, [field]: value })); const submit = (event) => { event.preventDefault(); onCreated({ ...initialJob, ...form }) }; return <div className="modal-backdrop" role="presentation" onMouseDown={onClose}><section className="modal job-modal" role="dialog" aria-modal="true" aria-labelledby="job-modal-title" onMouseDown={(event) => event.stopPropagation()}><button className="icon-button modal-close" onClick={onClose} aria-label="Close dialog"><X size={18} /></button><div className="modal-mark"><Wrench size={20} /></div><h2 id="job-modal-title">Create Maintenance Job</h2><p>Turn the P-104 prediction into an assigned field action.</p><form onSubmit={submit}><div className="form-grid">{[['asset', 'Asset'], ['issue', 'Detected issue'], ['action', 'Recommended action'], ['priority', 'Priority'], ['technician', 'Technician'], ['due', 'Due date'], ['duration', 'Estimated duration']].map(([field, label]) => <label key={field}>{label}<input value={form[field]} onChange={(event) => update(field, event.target.value)} /></label>)}</div><label>Notes<textarea value={form.notes} onChange={(event) => update('notes', event.target.value)} placeholder="Add instructions for the technician..." /></label><div className="modal-form-actions"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button icon={ClipboardCheck}>Create job</Button></div></form></section></div> }
function Sidebar({ mobileOpen, onClose }) { return <aside className={`sidebar ${mobileOpen ? 'sidebar-open' : ''}`}><div className="brand"><div className="brand-mark"><Zap size={18} fill="currentColor" /></div><div><strong>RakshaAI</strong><small>Asset intelligence platform</small></div><button className="icon-button mobile-close" onClick={onClose} aria-label="Close navigation"><X size={18} /></button></div><div className="workspace-switcher"><Building2 size={16} /><span>Northbridge Campus</span><ChevronDown size={14} /></div><nav aria-label="Primary navigation"><p className="nav-label">Workspace</p>{navItems.map(({ label, icon: Icon, count, path }) => <Link to={path} key={label} className={`nav-item ${label === 'Dashboard' ? 'active' : ''}`} onClick={onClose}><Icon size={18} /><span>{label}</span>{count && <em>{count}</em>}</Link>)}<p className="nav-label nav-label-spaced">Manage</p><Link to="/technician" className="nav-item"><Users size={18} /><span>Technicians</span></Link><Link to="/settings" className="nav-item"><Settings size={18} /><span>Settings</span></Link></nav><div className="sidebar-footer"><div className="system-status"><span className="status-dot" />All systems operational</div><p>Last synced 2 min ago</p></div></aside> }
function TopBar({ onMenu, onBrief }) { const navigate = useNavigate(); return <header className="topbar"><button className="icon-button menu-trigger" onClick={onMenu} aria-label="Open navigation"><Menu size={20} /></button><div className="top-search"><Search size={17} /><input aria-label="Search assets" placeholder="Search assets, jobs, alerts..." /><kbd>⌘ K</kbd></div><div className="top-actions"><button className="icon-button" onClick={onBrief} aria-label="View AI brief"><Sparkles size={18} /></button><button className="icon-button notification-button" onClick={() => navigate('/alerts')} aria-label="Open notifications"><Bell size={18} /><span /></button><div className="profile"><div className="avatar">MC</div><div className="profile-copy"><strong>Marcus Chen</strong><small>Operations lead</small></div><ChevronDown size={15} /></div></div></header> }
function PageHeader({ onBrief }) { return <div className="page-header"><div><div className="breadcrumb">Workspace <span>/</span> Dashboard</div><h1>What needs your attention right now?</h1><p>Live operational intelligence across Northbridge Campus.</p></div><div className="header-actions"><Button variant="secondary" icon={FileText}>Export report</Button><Button icon={Sparkles} onClick={onBrief}>AI brief</Button></div></div> }
function SensorCard({ sensor, onSelect, selected }) { const change = `${sensor.percentageChange >= 0 ? '+' : ''}${sensor.percentageChange.toFixed(1)}%`; return <button type="button" className={`sensor-card ${selected ? 'sensor-card-selected' : ''}`} onClick={() => onSelect(sensor.id)}><div className="sensor-card-heading"><div><div className="sensor-type"><span className="live-pulse" />LIVE <span>·</span> {sensor.type}</div><h3>{sensor.name}</h3></div><StatusBadge status={sensor.status} /></div><div className="sensor-reading"><div><strong>{sensor.formattedValue}</strong><span>{sensor.unit}</span><p>Current reading</p></div><div className={`sensor-change sensor-change-${sensor.status.toLowerCase()}`}>{change}<small>vs baseline</small></div></div><div className="sensor-sparkline"><ResponsiveContainer width="100%" height="100%"><AreaChart data={sensor.history}><Area type="monotone" dataKey="value" stroke={sensor.status === 'Critical' ? '#d34b53' : '#c88216'} fill={sensor.status === 'Critical' ? '#fff0f1' : '#fff5df'} strokeWidth={1.7} dot={false} isAnimationActive={false} /></AreaChart></ResponsiveContainer></div><div className="sensor-updated"><span><span className="status-dot" />Receiving data</span><span>{sensor.updatedAt.toLocaleTimeString([], { minute: '2-digit', second: '2-digit' })}</span></div></button> }
function CriticalAlert({ onView }) { return <section className="critical-alert"><div className="critical-icon"><AlertTriangle size={21} /></div><div className="critical-copy"><div className="critical-kicker">CRITICAL <span>— FAILURE IMMINENT</span></div><h2>Pump P-104</h2><strong>89% failure probability within 6 hours</strong><p>Triggered by: <span>Vibration rising</span> · <span>Temperature rising</span> · <span>Pressure falling</span> · <span>Humidity increasing</span> · <span>Water flow decreasing</span></p><p>Likely cause: <b>Bearing degradation</b> · Confidence: <b>91%</b></p></div><div className="critical-actions"><Button variant="secondary" onClick={onView}>View Asset</Button><Button onClick={() => window.location.assign('/assets/P-104')}>Create Maintenance Job</Button></div></section> }
function RecommendedAction({ onCreate }) { return <section className="recommendation"><div className="recommendation-heading"><div><p className="eyebrow">Prioritize · AI recommendation</p><h2>Recommended Action</h2></div><Badge tone="critical">Immediate</Badge></div><div className="recommendation-body"><div><h3>Inspect drive-end bearing within 24 hours</h3><p>Abnormal vibration + elevated temperature + declining flow</p></div><div className="recommendation-facts"><div><span>Estimated maintenance</span><strong>2.5 hours</strong></div><div><span>Downtime if ignored</span><strong>~18 hours</strong></div><div><span>Estimated cost</span><strong>₹48,000</strong></div></div></div><Button icon={Wrench} onClick={onCreate}>Create Maintenance Job</Button></section> }
function SensorDetail({ sensor, windowSize, setWindowSize, evidence }) { const windows = [{ label: 'Last 1 minute', size: 40 }, { label: 'Last 5 minutes', size: 60 }, { label: 'Last 15 minutes', size: 60 }, { label: 'Last 1 hour', size: 60 }]; return <section className="panel sensor-detail"><div className="panel-heading"><div><p className="eyebrow">Selected sensor · Pump P-104</p><h2>{sensor.name}</h2></div><StatusBadge status={sensor.status} /></div><div className="detail-reading"><strong>{sensor.formattedValue}</strong><span>{sensor.unit}</span><Badge tone={sensor.status.toLowerCase()}>{sensor.percentageChange >= 0 ? '+' : ''}{sensor.percentageChange.toFixed(1)}% vs baseline</Badge></div>{evidence && <div className="sensor-evidence"><strong>{evidence.title}</strong><span>{evidence.description}</span><b>Evidence: {sensor.formattedValue} {sensor.unit} vs baseline {sensor.baseline} {sensor.unit}</b></div>}<div className="chart-key"><span><i className="key-live" />Actual value</span><span><i className="key-baseline" />Baseline</span><span><i className="key-warning" />Warning / critical thresholds</span></div><SensorChart sensor={sensor} windowSize={windowSize} highlightTimestamp={sensor.updatedAt} /><div className="chart-controls">{windows.map((item) => <button type="button" key={item.label} className={windowSize === item.size ? 'active' : ''} onClick={() => setWindowSize(item.size)}>{item.label}</button>)}</div><dl className="detail-meta"><div><dt>Baseline</dt><dd>{sensor.baseline} {sensor.unit}</dd></div><div><dt>Normal range</dt><dd>{sensor.normalRange}</dd></div><div><dt>Warning threshold</dt><dd>{sensor.warningThreshold} {sensor.unit}</dd></div><div><dt>Critical threshold</dt><dd>{sensor.criticalThreshold} {sensor.unit}</dd></div><div><dt>Last updated</dt><dd>{sensor.updatedAt.toLocaleTimeString()}</dd></div></dl></section> }
function Queue() { return <section className="panel queue-panel"><div className="panel-heading"><div><p className="eyebrow">Act · maintenance queue</p><h2>Priority actions</h2></div><Button variant="ghost" icon={ArrowUpRight}>View queue</Button></div><div className="table-scroll"><table><thead><tr><th>Asset</th><th>Risk</th><th>Priority</th><th>Issue</th><th>Downtime</th><th>Cost</th></tr></thead><tbody>{maintenanceQueue.map((item) => <tr key={item.asset}><td><strong>{item.asset}</strong></td><td><strong className="health-critical">{item.risk}</strong></td><td><StatusBadge status={item.priority === 'High' ? 'Warning' : item.priority === 'Medium' ? 'Normal' : 'Critical'} /></td><td>{item.issue}</td><td>{item.downtime}</td><td>{item.cost}</td></tr>)}</tbody></table></div></section> }
function RiskAndDistribution({ sensors }) { const vibration = sensors.find((sensor) => sensor.id === 'vibration'); const liveRisk = vibration.history.map((point) => ({ label: point.timestamp.getTime(), risk: Math.min(100, Math.max(0, 40 + ((point.value - vibration.baseline) / (vibration.criticalThreshold - vibration.baseline)) * 49)) })); const distribution = [{ label: 'Normal', value: 91, color: '#159a70' }, { label: 'Warning', value: 24, color: '#c88216' }, { label: 'Critical', value: 12, color: '#d34b53' }]; return <section className="lower-grid"><article className="panel risk-panel"><div className="panel-heading"><div><p className="eyebrow">Predict · live derived risk</p><h2>P-104 failure risk trend</h2></div><Badge tone="critical">89% · 6h window</Badge></div><div className="risk-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={liveRisk}><defs><linearGradient id="liveRiskFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#d34b53" stopOpacity={0.24} /><stop offset="100%" stopColor="#d34b53" stopOpacity={0} /></linearGradient></defs><XAxis dataKey="label" type="number" domain={['dataMin', 'dataMax']} tickFormatter={(value) => new Date(value).toLocaleTimeString([], { minute: '2-digit', second: '2-digit' })} axisLine={false} tickLine={false} tick={{ fill: '#8b98a9', fontSize: 10 }} /><YAxis domain={[0, 100]} tickFormatter={(value) => `${value}%`} axisLine={false} tickLine={false} tick={{ fill: '#8b98a9', fontSize: 10 }} width={34} /><CartesianGrid stroke="#edf1f4" vertical={false} /><Tooltip labelFormatter={(value) => new Date(value).toLocaleTimeString()} formatter={(value) => [`${Number(value).toFixed(0)}%`, 'Failure risk']} /><Area type="monotone" dataKey="risk" stroke="#d34b53" strokeWidth={2.5} fill="url(#liveRiskFill)" dot={false} isAnimationActive={false} /></AreaChart></ResponsiveContainer></div></article><article className="panel distribution-panel"><div className="panel-heading"><div><p className="eyebrow">Fleet health</p><h2>Asset distribution</h2></div><Gauge size={18} className="muted" /></div><div className="distribution-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={distribution} layout="vertical" margin={{ left: 5, right: 16 }}><XAxis type="number" hide /><YAxis dataKey="label" type="category" axisLine={false} tickLine={false} tick={{ fill: '#718096', fontSize: 11 }} width={58} /><Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={14}>{distribution.map((item) => <Cell key={item.label} fill={item.color} />)}</Bar></BarChart></ResponsiveContainer></div><div className="distribution-total"><strong>127</strong><span>Assets monitored</span></div></article></section> }
function ActivityPanel() { return <section className="lower-grid activity-grid"><article className="panel"><div className="panel-heading"><div><p className="eyebrow">Explain · anomalies</p><h2>Recent anomalies</h2></div><MoreHorizontal size={18} className="muted" /></div><div className="activity-list"><div><span className="activity-dot critical" /><div><strong>Bearing degradation signature detected</strong><p>P-104 · 2 minutes ago</p></div><Badge tone="critical">Critical</Badge></div><div><span className="activity-dot warning" /><div><strong>Temperature trend exceeded model band</strong><p>CH-04 · 18 minutes ago</p></div><Badge tone="warning">Review</Badge></div></div></article><article className="panel"><div className="panel-heading"><div><p className="eyebrow">Verify · completed work</p><h2>Recent maintenance activity</h2></div><MoreHorizontal size={18} className="muted" /></div><div className="activity-list"><div><span className="activity-icon"><ClipboardCheck size={14} /></span><div><strong>Filter replacement completed</strong><p>AHU-21 · Today, 09:42</p></div><Badge tone="healthy">Verified</Badge></div><div><span className="activity-icon"><Wrench size={14} /></span><div><strong>Lubrication service logged</strong><p>P-098 · Yesterday, 16:20</p></div><Badge tone="neutral">Closed</Badge></div></div></article></section> }

function RecommendationDock() { const { createJob } = useJobs(); const [open, setOpen] = useState(false); const [created, setCreated] = useState(false); const submit = (job) => { createJob(job); setOpen(false); setCreated(true); window.setTimeout(() => setCreated(false), 5000) }; return <><div className="workflow-dock"><RecommendedAction onCreate={() => setOpen(true)} /></div>{open && <CreateJobModal onClose={() => setOpen(false)} onCreated={submit} />}{created && <div className="toast" role="status"><ClipboardCheck size={17} /><span><strong>Maintenance Job M-2041 created successfully.</strong><small>It is now ready for assignment.</small></span><button className="icon-button" onClick={() => setCreated(false)} aria-label="Dismiss notification"><X size={15} /></button></div>}</> }
function AssetDetailRoute() { const { id = 'P-104' } = useParams(); return <><AssetDetailPage /><>{id === 'P-104' && <RecommendationDock />}</></> }
function MaintenancePage() { const { jobs, updateJob } = useJobs(); const [activeTab, setActiveTab] = useState('Open Jobs'); const visible = activeTab === 'Open Jobs' ? jobs.filter((job) => job.status !== 'Resolved') : activeTab === 'Completed' ? jobs.filter((job) => job.status === 'Resolved') : jobs.filter((job) => job.status === activeTab.slice(0, -1)); const act = (job, status) => updateJob(job.id, { status }); return <AppFrame title="Maintenance" subtitle="Turn predictions into assigned work and verify every repair."><div className="maintenance-tabs">{['Open Jobs', 'Assigned', 'In Progress', 'Completed'].map((tab) => <button key={tab} className={activeTab === tab ? 'active' : ''} onClick={() => setActiveTab(tab)}>{tab}<span>{tab === 'Open Jobs' ? jobs.filter((job) => job.status !== 'Resolved').length : tab === 'Completed' ? jobs.filter((job) => job.status === 'Resolved').length : jobs.filter((job) => job.status === tab.slice(0, -1)).length}</span></button>)}</div><section className="panel maintenance-table"><div className="panel-heading"><div><p className="eyebrow">Act · operational queue</p><h2>{activeTab}</h2></div><Badge tone="neutral">{visible.length} jobs</Badge></div><div className="table-scroll"><table><thead><tr><th>Job</th><th>Asset</th><th>Issue</th><th>Priority</th><th>Technician</th><th>Status</th><th>Action</th></tr></thead><tbody>{visible.map((job) => <tr key={job.id}><td><Link className="job-link" to={`/maintenance/${job.id}`}>{job.id}</Link></td><td>{job.asset}</td><td>{job.issue}</td><td><StatusBadge status={job.priority} /></td><td>{job.technician || 'Unassigned'}</td><td>{job.status}</td><td><div className="job-actions">{job.status === 'Predicted issue' && <Button variant="ghost" onClick={() => act(job, 'Job created')}>Create</Button>}{job.status === 'Job created' && <Button variant="ghost" onClick={() => act(job, 'Technician assigned')}>Assign</Button>}{job.status === 'Technician assigned' && <Button variant="ghost" onClick={() => act(job, 'Inspection')}>Start Job</Button>}{job.status === 'Inspection' && <Button variant="ghost" onClick={() => act(job, 'Repair')}>Start Repair</Button>}{job.status === 'Repair' && <Button variant="ghost" onClick={() => act(job, 'Resolved')}>Mark Resolved</Button>}<Link className="text-link" to={`/assets/${job.assetId}`}>View Asset</Link></div></td></tr>)}</tbody></table></div></section></AppFrame> }
function JobDetailPage() { const { id = 'M-2041' } = useParams(); const { jobs, updateJob } = useJobs(); const job = jobs.find((item) => item.id === id) || initialJob; const { sensors } = useLiveSensors(); const next = { 'Predicted issue': 'Job created', 'Job created': 'Technician assigned', 'Technician assigned': 'Inspection', Inspection: 'Repair', Repair: 'Resolved' }[job.status]; return <AppFrame title={`Maintenance Job ${job.id}`} subtitle="Evidence-led work order and resolution trail."><div className="job-detail-layout"><section className="panel job-overview"><div className="asset-kicker"><span className="asset-icon"><Wrench size={17} /></span><span>{job.asset} · {job.issue}</span><StatusBadge status={job.priority} /></div><h2>{job.action}</h2><div className="job-fact-grid"><div><span>Technician</span><strong>{job.technician}</strong></div><div><span>Due</span><strong>{job.due}</strong></div><div><span>Duration</span><strong>{job.duration}</strong></div><div><span>Current status</span><strong>{job.status}</strong></div></div><Button onClick={() => next && updateJob(job.id, { status: next })}>{next === 'Resolved' ? 'Mark Resolved' : next || 'Resolved'}</Button></section><section className="panel job-timeline"><p className="eyebrow">Workflow trace</p><h2>Predict → Prioritize → Act</h2><div className="job-steps">{['Predicted issue', 'Job created', 'Technician assigned', 'Inspection', 'Repair', 'Resolved'].map((step) => <div className={step === job.status ? 'current' : ['Predicted issue', 'Job created', 'Technician assigned', 'Inspection', 'Repair', 'Resolved'].indexOf(step) < ['Predicted issue', 'Job created', 'Technician assigned', 'Inspection', 'Repair', 'Resolved'].indexOf(job.status) ? 'complete' : ''} key={step}><span>{step === job.status ? '●' : '✓'}</span>{step}</div>)}</div></section></div><div className="job-detail-columns"><section className="panel"><p className="eyebrow">Supporting sensor evidence</p><h2>Signals behind the prediction</h2><div className="job-evidence">{sensors.map((sensor) => <div key={sensor.id}><strong>{sensor.type}</strong><span>{sensor.formattedValue} {sensor.unit}</span><Badge tone={sensor.status.toLowerCase()}>{sensor.status}</Badge></div>)}</div></section><section className="panel"><p className="eyebrow">Explain</p><h2>AI explanation</h2><p className="explanation-copy">Abnormal vibration and elevated temperature, combined with declining flow and pressure, point to bearing degradation. Inspect the drive-end bearing before the projected failure window.</p><div className="recommended-line"><Wrench size={16} />{job.action}</div></section></div></AppFrame> }
function TechnicianPage() { const { jobs, updateJob } = useJobs(); const job = jobs[0] || initialJob; const { sensors } = useLiveSensors(); return <AppFrame title="Technician workspace" subtitle="A focused field view for the next safe action."><section className="technician-hero"><div className="tech-alert">🔴 Pump P-104</div><h2>Fix bearing issue</h2><Badge tone="critical">{job.status}</Badge><div className="tech-action"><span>What should I do?</span><strong>Inspect drive-end bearing.</strong><Button icon={Wrench} onClick={() => updateJob(job.id, { status: 'Inspection' })}>Start Maintenance</Button></div></section><div className="technician-grid"><section className="panel tech-panel"><h2>What happened?</h2><p>Vibration increased significantly.</p><h2>Why?</h2><p>Temperature and vibration are outside normal operating conditions.</p><h2>How urgent?</h2><strong className="health-critical">Within 24 hours</strong></section><section className="panel tech-panel"><p className="eyebrow">Field context</p><h2>Utilities plant</h2><p>Asset location: Boiler feed pump bay · Runtime 18,426 hours</p><div className="safety-note"><AlertTriangle size={16} /><span><strong>Safety note</strong> Isolate power and depressurize before opening the housing.</span></div><p className="eyebrow tech-sensors-label">Relevant sensors</p><div className="tech-sensors">{sensors.slice(0, 3).map((sensor) => <div key={sensor.id}><strong>{sensor.type}</strong><span>{sensor.formattedValue} {sensor.unit}</span></div>)}</div></section><section className="panel tech-panel"><p className="eyebrow">AI explanation</p><h2>Bearing degradation</h2><p>Rising vibration is the earliest warning signal. Heat is increasing as friction grows, while flow is falling.</p><p className="eyebrow">Maintenance history</p><p>Last service: 34 days ago · Estimated task: 2.5 hours</p></section></div></AppFrame> }

function AssetsPage() { const [search, setSearch] = useState(''); const [type, setType] = useState('All types'); const [status, setStatus] = useState('All status'); const [riskSort, setRiskSort] = useState('none'); const [healthSort, setHealthSort] = useState('none'); const navigate = useNavigate(); const filteredAssets = assetCatalog.filter((asset) => asset.name.toLowerCase().includes(search.toLowerCase()) && (type === 'All types' || asset.type === type) && (status === 'All status' || asset.status === status)).sort((a, b) => riskSort === 'desc' ? b.risk - a.risk : riskSort === 'asc' ? a.risk - b.risk : healthSort === 'desc' ? b.health - a.health : healthSort === 'asc' ? a.health - b.health : 0); return <AppFrame title="Asset register" subtitle="Monitor health, risk, and anomalies across every connected asset." onBrief={() => {}}><div className="asset-page-head"><div><p className="eyebrow">Fleet inventory</p><h2>All assets</h2><p>{filteredAssets.length} of {assetCatalog.length} assets shown</p></div><div className="asset-summary"><span><i className="dot-critical" />2 Critical</span><span><i className="dot-warning" />3 Warning</span><span><i className="dot-normal" />2 Normal</span></div></div><div className="asset-filters"><label className="filter-search"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} aria-label="Search assets" placeholder="Search by asset name or ID" /></label><select value={type} onChange={(event) => setType(event.target.value)} aria-label="Filter by asset type"><option>All types</option><option>Pump</option><option>Motor</option><option>Generator</option><option>HVAC</option></select><select value={status} onChange={(event) => setStatus(event.target.value)} aria-label="Filter by status"><option>All status</option><option>Critical</option><option>Warning</option><option>Normal</option></select><button className={`sort-button ${riskSort !== 'none' ? 'selected' : ''}`} onClick={() => { setRiskSort(riskSort === 'desc' ? 'asc' : 'desc'); setHealthSort('none') }}>Risk {riskSort === 'desc' ? '↓' : riskSort === 'asc' ? '↑' : '↕'}</button><button className={`sort-button ${healthSort !== 'none' ? 'selected' : ''}`} onClick={() => { setHealthSort(healthSort === 'desc' ? 'asc' : 'desc'); setRiskSort('none') }}>Health {healthSort === 'desc' ? '↓' : healthSort === 'asc' ? '↑' : '↕'}</button><button className="sort-button" onClick={() => setRiskSort('desc')}>Recent anomaly</button></div><div className="asset-grid">{filteredAssets.map((asset) => <button key={asset.id} className="asset-list-card" onClick={() => navigate(`/assets/${asset.id}`)}><div className="asset-list-top"><div className="asset-icon"><Truck size={18} /></div><StatusBadge status={asset.status} /></div><div className="asset-list-title"><strong>{asset.name}</strong><span>{asset.type} · {asset.location}</span></div><div className="asset-list-metrics"><div><span>Health</span><strong className={`health-${asset.status.toLowerCase()}`}>{asset.health}/100</strong></div><div><span>Risk</span><strong className={`health-${asset.status.toLowerCase()}`}>{asset.risk}%</strong></div><div><span>Signal</span><strong>{asset.anomaly}</strong></div></div><div className="asset-list-footer"><span>{asset.updated}</span><ArrowUpRight size={15} /></div></button>)}</div></AppFrame> }

function AnomalyTimeline({ selected, onSelect }) { const anomalies = [{ time: '10:20', severity: 'Normal', sensorId: 'temperature', description: 'Temperature within normal operating band.' }, { time: '11:05', severity: 'Warning', sensorId: 'vibration', description: 'Vibration rising above the expected model band.' }, { time: '11:47', severity: 'Critical', sensorId: 'temperature', description: 'Temperature abnormal for current load.' }, { time: '12:10', severity: 'Warning', sensorId: 'flow', description: 'Water flow decreasing below normal range.' }, { time: '12:18', severity: 'Critical', sensorId: 'vibration', description: 'AI anomaly detected in bearing signature.' }, { time: '12:25', severity: 'Critical', sensorId: 'vibration', description: 'Failure risk crossed critical threshold.' }]; return <section className="panel timeline-panel"><div className="panel-heading"><div><p className="eyebrow">Explain · signal history</p><h2>Anomaly timeline</h2></div><Badge tone="critical">6 events</Badge></div><div className="timeline">{anomalies.map((anomaly) => <button type="button" key={`${anomaly.time}-${anomaly.description}`} className={`timeline-item ${selected === anomaly.sensorId ? 'selected' : ''}`} onClick={() => onSelect(anomaly.sensorId, anomaly)}><span className={`timeline-marker timeline-${anomaly.severity.toLowerCase()}`} /><span className="timeline-time">{anomaly.time}</span><span className="timeline-content"><strong>{anomaly.description}</strong><small>{anomaly.sensorId === 'vibration' ? 'VibraSense V-104' : anomaly.sensorId === 'temperature' ? 'ThermoSense T-104' : 'FlowPulse F-104'} · <em>{anomaly.severity}</em></small></span><ArrowUpRight size={14} /></button>)}</div></section> }
function ExplainRisk({ sensors, whyOpen, setWhyOpen }) { const rows = [{ id: 'vibration', label: 'Vibration', live: 'mm/s' }, { id: 'temperature', label: 'Temperature', live: '°C' }, { id: 'pressure', label: 'Pressure', live: 'bar' }, { id: 'humidity', label: 'Humidity', live: '%' }, { id: 'flow', label: 'Water Flow', live: 'L/min' }]; return <section className="panel explain-panel"><div className="panel-heading"><div><p className="eyebrow">Explain · model evidence</p><h2>Why is P-104 at risk?</h2></div><button className="why-button" onClick={() => setWhyOpen(!whyOpen)}>Why? <span>i</span></button></div>{whyOpen && <div className="why-copy">Multiple signals are moving away from their healthy baselines together. That combination is consistent with bearing friction: vibration rises first, heat follows, and flow and pressure weaken as efficiency drops.</div>}<div className="evidence-table"><div className="evidence-head"><span>Signal</span><span>Current</span><span>Baseline</span><span>Change</span></div>{rows.map((row) => { const sensor = sensors.find((item) => item.id === row.id); return <div className="evidence-row" key={row.id}><strong>{row.label}</strong><span>{sensor.formattedValue} {row.live}</span><span>{sensor.baseline} {row.live}</span><b className={`health-${sensor.status.toLowerCase()}`}>{sensor.percentageChange >= 0 ? '+' : ''}{sensor.percentageChange.toFixed(1)}%</b></div> })}</div><div className="cause-block"><div><span>Root cause</span><strong>Bearing degradation — 76% confidence</strong></div><div><span>Secondary causes</span><p>Shaft misalignment <b>14%</b> · Lubrication issue <b>7%</b> · Other <b>3%</b></p></div></div></section> }
function DigitalTwin({ sensors }) { const vibration = sensors.find((sensor) => sensor.id === 'vibration'); const temperature = sensors.find((sensor) => sensor.id === 'temperature'); return <section className="panel twin-panel"><div className="panel-heading"><div><p className="eyebrow">Act · asset intelligence</p><h2>Digital twin</h2></div><Badge tone="critical">Bearing highlighted</Badge></div><div className="twin-layout"><div className="pump-illustration"><div className="twin-label motor-label">Motor</div><div className="twin-motor" /><div className="twin-label shaft-label">Shaft</div><div className="twin-shaft" /><div className="twin-label bearing-label">Bearing</div><div className="twin-bearing"><span /></div><div className="twin-label impeller-label">Impeller</div><div className="twin-impeller" /><div className="twin-housing" /><div className="twin-label housing-label">Housing</div></div><div className="twin-facts"><div><span>Vibration</span><strong className="health-critical">{vibration.formattedValue} mm/s</strong><small>Risk contribution 42%</small></div><div><span>Temperature</span><strong className="health-critical">{temperature.formattedValue} °C</strong><small>Risk contribution 21%</small></div><div><span>Confidence</span><strong>76%</strong><small>Bearing degradation</small></div></div></div></section> }

function PostMaintenanceVerification() { return <section className="panel verification-panel"><div className="panel-heading"><div><p className="eyebrow">Verify · M-2041 resolved</p><h2>Post-Maintenance Verification</h2></div><Badge tone="healthy">Healthy / Restored</Badge></div><p className="verification-intro">Repair evidence confirms the bearing intervention restored the asset to a stable operating state.</p><div className="before-after"><div className="verification-column before"><h3>Before</h3><div><span>Vibration</span><strong>3.8 mm/s</strong></div><div><span>Temperature</span><strong>86°C</strong></div><div><span>Health</span><strong>72</strong></div><div><span>Failure Risk</span><strong>89%</strong></div></div><div className="verification-arrow">→</div><div className="verification-column after"><h3>After</h3><div><span>Vibration</span><strong>2.2 mm/s</strong></div><div><span>Temperature</span><strong>73°C</strong></div><div><span>Health</span><strong>96</strong></div><div><span>Failure Risk</span><strong>8%</strong></div></div></div><div className="verification-bars"><div><span>Health restored</span><div><i style={{ width: '72%' }} /><i className="after-bar" style={{ width: '96%' }} /></div><b>72 → 96</b></div><div><span>Failure risk reduced</span><div><i className="risk-before" style={{ width: '89%' }} /><i className="risk-after" style={{ width: '8%' }} /></div><b>89% → 8%</b></div></div><div className="verification-checks"><span>✅ Anomaly resolved</span><span>✅ Risk substantially reduced</span><span>✅ Asset health restored</span></div></section> }
function JobDetailRoute() { const { id = 'M-2041' } = useParams(); const { jobs } = useJobs(); const job = jobs.find((item) => item.id === id) || initialJob; return <><JobDetailPage />{job.status === 'Resolved' && <PostMaintenanceVerification />}</> }
const landingNav = [{ label: 'Dashboard', path: '/dashboard' }, { label: 'Assets', path: '/assets' }, { label: 'Maintenance', path: '/maintenance' }, { label: 'Alerts', path: '/alerts' }, { label: 'Analytics', path: '/analytics' }]
const landingWorkflow = [{ label: 'Detect', copy: 'Continuous monitoring of sensors to detect anomalies in real time.', icon: Activity, tone: 'blue' }, { label: 'Explain', copy: 'AI explains why an asset is at risk with clear evidence and root cause.', icon: Sparkles, tone: 'violet' }, { label: 'Prioritize', copy: 'Assets are ranked by risk, downtime and cost to help you focus.', icon: ClipboardCheck, tone: 'amber' }, { label: 'Act', copy: 'Create maintenance jobs, assign technicians and take action.', icon: Wrench, tone: 'green' }, { label: 'Verify', copy: 'Verify repair effectiveness and ensure risk is reduced.', icon: ShieldCheck, tone: 'lime' }]

function LandingDashboardPreview() { return <div className="landing-visual" aria-label="rakshaAI dashboard preview"><div className="preview-window"><div className="preview-sidebar"><span /><span className="active" /><span /><span /><span /></div><div className="preview-content"><div className="preview-heading"><span>Overview</span><MoreHorizontal size={13} /></div><div className="preview-metrics"><div><small>Assets Monitored</small><strong>127</strong><b>All Systems Online</b></div><div><small>Critical Alerts</small><strong className="preview-red">12</strong><b className="preview-red">Require Immediate Action</b></div><div><small>Health Score</small><strong className="preview-green">72%</strong><b>Average Across All Assets</b></div><div><small>Downtime Avoided</small><strong>210+ hrs</strong><b>This Month</b></div></div><div className="preview-panels"><div className="preview-panel distribution-preview"><small>Asset Health Distribution</small><div className="preview-donut"><span>127</span></div><div className="preview-legend"><span><i className="legend-normal" />Normal <b>91</b></span><span><i className="legend-warning" />Warning <b>24</b></span><span><i className="legend-critical" />Critical <b>12</b></span></div></div><div className="preview-panel risks-preview"><small>Top Risk Assets <em>View All Assets →</em></small><div><span>Pump P-104</span><b>81%</b><i>Critical</i></div><div><span>Motor M-087</span><b>63%</b><i>High</i></div><div><span>HVAC-21</span><b>48%</b><i>Warning</i></div><div><span>Generator G-03</span><b className="normal-text">22%</b><i className="normal-text">Normal</i></div></div></div><div className="preview-panel preview-chart"><small>Failure Risk Trend <em>7 Days⌄</em></small><svg viewBox="0 0 360 85" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="previewFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#24c4e8" stopOpacity=".32" /><stop offset="1" stopColor="#24c4e8" stopOpacity="0" /></linearGradient></defs><path d="M0 74 C28 69 32 52 57 59 S88 45 111 51 S148 42 168 38 S196 45 216 31 S239 36 258 21 S291 31 310 12 S336 23 360 4 L360 85 L0 85Z" fill="url(#previewFill)" /><path d="M0 74 C28 69 32 52 57 59 S88 45 111 51 S148 42 168 38 S196 45 216 31 S239 36 258 21 S291 31 310 12 S336 23 360 4" fill="none" stroke="#27c9ec" strokeWidth="2" /></svg></div></div></div><div className="motor-video-wrap"><video className="motor-video" autoPlay muted loop playsInline preload="metadata" src="/motor.mp4" aria-label="Industrial motor running under sensor monitoring" /></div></div> }

function LandingPage() { const [menuOpen, setMenuOpen] = useState(false); return <div className="landing-page"><header className="landing-header"><Link className="landing-brand" to="/"><span className="landing-brand-mark"><Zap size={21} fill="currentColor" /></span><span><strong>raksha<span>AI</span></strong><small>AI-Powered Maintenance</small></span></Link><button className="landing-menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle navigation menu" aria-expanded={menuOpen}><Menu size={22} /></button><nav className={`landing-nav ${menuOpen ? 'landing-nav-open' : ''}`} aria-label="Landing page navigation">{landingNav.map((item) => <Link key={item.label} to={item.path} onClick={() => setMenuOpen(false)}>{item.label}</Link>)}</nav><div className="landing-actions"><Link className="landing-login" to="/dashboard">Log In</Link><Link className="landing-start" to="/dashboard">Get Started</Link></div></header><main><section className="landing-hero"><div className="landing-hero-copy"><div className="landing-eyebrow">AI-Powered <span>•</span> IoT-Enabled <span>•</span> Always Monitoring</div><h1>Predict Failures.<br /><span>Prevent Downtime.</span></h1><p>rakshaAI uses real-time sensor data and AI to detect anomalies, predict failures, and help your team take action before breakdowns occur.</p><div className="landing-cta"><Link className="landing-primary-cta" to="/dashboard">Book a Demo <ArrowUpRight size={17} /></Link><Link className="landing-secondary-cta" to="/dashboard"><Play size={14} fill="currentColor" />Watch Overview</Link></div><div className="trusted-row"><span>Trusted by leading teams<br />in manufacturing &amp; facilities</span><strong>SIEMENS</strong><strong>SCHNEIDER<br /><small>ELECTRIC</small></strong><strong>ABB</strong><strong>TATA</strong><strong>Reliance<small>Industries Limited</small></strong></div></div><LandingDashboardPreview /></section><section className="workflow-section"><div className="workflow-title">End-to-End Predictive Maintenance Workflow</div><div className="workflow-path"><span className="path-blue">Detect</span><i>→</i><span className="path-violet">Explain</span><i>→</i><span className="path-amber">Prioritize</span><i>→</i><span className="path-green">Act</span><i>→</i><span className="path-lime">Verify</span></div><div className="workflow-grid">{landingWorkflow.map(({ label, copy, icon: Icon, tone }) => <article key={label} className={`workflow-item workflow-item-${tone}`}><div className="workflow-item-icon"><Icon size={27} /></div><h2>{label}</h2><p>{copy}</p></article>)}</div></section></main></div> }

